<?php require dirname(__DIR__).'/app/bootstrap.php'; require_permission('content.view'); ensure_taxonomy_schema();
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['logout'])){verify_csrf();nowrd_audit('auth.logout','admin',(int)($_SESSION['admin_id']??0),'Administrator logged out');$_SESSION=[];if(ini_get('session.use_cookies')){$params=session_get_cookie_params();setcookie(session_name(),'',time()-42000,$params['path'],$params['domain'],$params['secure'],$params['httponly']);}session_destroy();header('Location: '.base_url('admin/login.php'));exit;}
$isAuthor = current_admin_role() === 'author';
if ($isAuthor) { $statQ=$pdo->prepare("SELECT COUNT(*) total, SUM(status='published') published FROM posts WHERE author_id=?"); $statQ->execute([(int)$_SESSION['admin_id']]); $stat=$statQ->fetch() ?: []; $total=(int)($stat['total']??0); $published=(int)($stat['published']??0); } else { $total=(int)$pdo->query('SELECT COUNT(*) FROM posts')->fetchColumn(); $published=(int)$pdo->query("SELECT COUNT(*) FROM posts WHERE status='published'")->fetchColumn(); } $drafts=$total-$published;
$search=trim((string)($_GET['q']??''));$status=(string)($_GET['status']??'');$category=(int)($_GET['category']??0);$page=max(1,(int)($_GET['page']??1));$perPage=(int)setting('dashboard_page_size','20');if(!in_array($perPage,[10,20,30,50],true))$perPage=20;
$where=[];$args=[];if($isAuthor){$where[]='p.author_id=?';$args[]=(int)$_SESSION['admin_id'];}if($search!==''){$where[]='(p.title LIKE ? OR p.excerpt LIKE ? OR p.content LIKE ?)';$like='%'.$search.'%';array_push($args,$like,$like,$like);}if(in_array($status,['draft','in_review','approved','published'],true)){$where[]='p.status=?';$args[]=$status;}if($category>0){$where[]='EXISTS (SELECT 1 FROM post_categories pc WHERE pc.post_id=p.id AND pc.category_id=?)';$args[]=$category;}$whereSql=$where?' WHERE '.implode(' AND ',$where):'';
$countQ=$pdo->prepare('SELECT COUNT(*) FROM posts p'.$whereSql);$countQ->execute($args);$filtered=(int)$countQ->fetchColumn();$pages=max(1,(int)ceil($filtered/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;
$q=$pdo->prepare('SELECT p.id,p.title,p.slug,p.status,p.updated_at,(SELECT GROUP_CONCAT(c.name ORDER BY c.name SEPARATOR ", ") FROM post_categories pc JOIN categories c ON c.id=pc.category_id WHERE pc.post_id=p.id) category_names FROM posts p'.$whereSql.' ORDER BY p.updated_at DESC LIMIT '.$perPage.' OFFSET '.$offset);$q->execute($args);$posts=$q->fetchAll();$categories=$pdo->query('SELECT id,name FROM categories ORDER BY name')->fetchAll();
function admin_query(array $overrides=[]): string { $v=array_merge($_GET,$overrides); foreach($v as $k=>$x) if($x===''||$x===null||$x===0||$x==='0') unset($v[$k]); return http_build_query($v); }
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard — NOWRD Studio</title><link rel="stylesheet" href="<?=e(base_url('public/assets/style.css'))?>"><style>.story-filters{display:flex;gap:9px;flex-wrap:wrap;padding:16px;border-bottom:1px solid var(--line)}.story-filters input,.story-filters select{min-width:0;border:1px solid var(--line);border-radius:9px;padding:10px 12px;font:inherit;background:#fff}.story-filters input{flex:1;min-width:160px}.story-filters .button{margin:0;white-space:nowrap}.story-filter-link{font-size:12px;color:var(--muted);align-self:center}.story-cats{display:block;color:var(--muted);font-size:11px;margin-top:4px}.pagination{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:16px;border-top:1px solid var(--line);font-size:12px;color:var(--muted)}.pagination a{color:var(--ink);font-weight:700}.filter-status{font-size:12px;color:var(--muted);padding:0 16px 12px}@media(max-width:520px){.story-filters{display:grid;grid-template-columns:1fr}.story-filters input{width:100%}}</style></head><body class="dashboard"><aside class="sidebar"><a class="brand" href="<?=e(base_url('index.php'))?>"><span class="brand-mark"><?=e(setting('brand_mark','n.'))?></span> <?=e(setting('brand_name','NOWRD'))?></a><div class="side-label">WORKSPACE</div><a class="side-link active" href="<?=e(base_url('admin/index.php'))?>">▦ &nbsp; Overview</a><a class="side-link" href="<?=e(base_url('admin/post.php'))?>">✎ &nbsp; New story</a><a class="side-link" href="<?=e(base_url('admin/media.php'))?>">▧ &nbsp; Media Library</a><a class="side-link" href="<?=e(base_url('admin/page-builder.php'))?>">▤ &nbsp; Page Builder</a><a class="side-link" href="<?=e(base_url('admin/taxonomies.php'))?>">◇ &nbsp; Categories & Tags</a><a class="side-link" href="<?=e(base_url('admin/settings.php'))?>">⚙ &nbsp; Settings</a><a class="side-link" href="<?=e(base_url('admin/users.php'))?>">♙ &nbsp; Admin accounts</a><a class="side-link" href="<?=e(base_url('admin/analytics.php'))?>">▥ &nbsp; Analytics</a><a class="side-link" href="<?=e(base_url('admin/maintenance.php'))?>">⌁ &nbsp; Maintenance</a><a class="side-link" href="<?=e(base_url('index.php'))?>">↗ &nbsp; View website</a><div class="side-bottom"><div class="avatar"><?=e(strtoupper(substr($_SESSION['admin_name']??'N',0,1)))?></div><div><b><?=e($_SESSION['admin_name']??'Editor')?></b><small>Administrator</small></div><form method="post" class="logout-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><button class="logout" type="submit" name="logout" value="1" aria-label="Logout">↗</button></form></div></aside><main class="admin-main"><header class="admin-top"><div><div class="eyebrow">YOUR WORKSPACE / OVERVIEW</div><h1>Good to see you<span class="lime">.</span></h1><?php if(setting('show_dashboard_welcome','1')==='1' && setting('editorial_mission','')!==''):?><p class="muted" style="max-width:560px;line-height:1.65;margin-top:10px"><?=e(setting('editorial_mission'))?></p><?php endif;?></div><a class="button" href="<?=e(base_url('admin/post.php'))?>">＋ New story</a></header><div class="stats"><div class="stat-card"><span>Total stories</span><strong><?=$total?></strong><small>All your writing</small></div><div class="stat-card"><span>Published</span><strong><?=$published?></strong><small>Live on the web</small></div><div class="stat-card"><span>Drafts</span><strong><?=$drafts?></strong><small>Still in progress</small></div></div><section class="table-panel"><div class="panel-head"><div><div class="eyebrow">YOUR CONTENT</div><h2>Stories</h2></div><span class="count"><?=$filtered?> MATCHING</span></div><form class="story-filters" method="get"><input name="q" value="<?=e($search)?>" placeholder="Search title, excerpt, or content…" aria-label="Search stories"><select name="status" aria-label="Filter status"><option value="">All statuses</option><option value="draft" <?=$status==='draft'?'selected':''?>>Drafts</option><option value="in_review" <?=$status==='in_review'?'selected':''?>>In review</option><option value="approved" <?=$status==='approved'?'selected':''?>>Approved</option><option value="published" <?=$status==='published'?'selected':''?>>Published</option></select><select name="category" aria-label="Filter category"><option value="0">All categories</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=$category===(int)$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><button class="button" type="submit">Filter</button><?php if($search!==''||$status!==''||$category):?><a class="story-filter-link" href="<?=e(base_url('admin/index.php'))?>">Clear</a><?php endif;?></form><?php if(!$posts): ?><div class="empty small-empty"><div class="empty-icon">✳</div><h3><?=$filtered?'No stories match these filters.':'Start with a blank page.'?></h3><p><?=$filtered?'Try another keyword or clear your filters.':'Your next idea could be the first story here.'?></p><?php if(!$filtered):?><a class="button" href="<?=e(base_url('admin/post.php'))?>">Create a story ↗</a><?php endif;?></div><?php else: ?><div class="table-scroll"><table><thead><tr><th>Title</th><th>Status</th><th>Last updated</th><th></th></tr></thead><tbody><?php foreach($posts as $p): ?><tr><td><b><?=e($p['title'])?></b><small>/<?=e($p['slug'])?></small><?php if($p['category_names']):?><span class="story-cats"><?=e($p['category_names'])?></span><?php endif;?></td><td><span class="status <?=e($p['status'])?>"><?=e(ucfirst($p['status']))?></span></td><td><?=e(date('M d, Y',strtotime($p['updated_at'])))?></td><td><a class="edit-link" href="<?=e(base_url('admin/post.php?id='.$p['id']))?>">Edit ↗</a> &nbsp; <a class="edit-link" href="<?=e(base_url('admin/translations.php?post_id='.$p['id']))?>">Translate ↗</a></td></tr><?php endforeach; ?></tbody></table></div><div class="pagination"><span>Page <?=$page?> of <?=$pages?></span><span><?php if($page>1):?><a href="?<?=e(admin_query(['page'=>$page-1]))?>">← Previous</a><?php endif;?> <?php if($page<$pages):?><a href="?<?=e(admin_query(['page'=>$page+1]))?>">Next →</a><?php endif;?></span></div><?php endif; ?></section><footer class="admin-footer"><?=e(strtoupper(setting('brand_name','NOWRD')))?> STUDIO <span><?=e(setting('brand_tagline','Made for the curious ✳'))?></span></footer></main><script>window.NOWRD_VISUAL = <?=json_encode(nowrd_visual_preferences(), JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>; window.NOWRD_VISUAL_ADMIN = true; window.NOWRD_CSRF = <?=json_encode(csrf_token())?>; window.NOWRD_VISUAL_SAVE_URL = <?=json_encode(base_url('admin/visual-settings.php'))?>;</script><script src="<?=e(base_url('public/assets/ui-v10.js'))?>" defer></script>
